~\cite{dialgebra nilsol}
Let $(P,\cdot,\circ)$ be a dialgebra and $A$ be a subalgebra of $P$. The \textbf{derived series} of $A$ is defined by
\begin{eqnarray*}
&&A^{(0)} := A, \qquad A^{(n+1)} := A^{(n)}\!\cdot\! A^{(n)} + A^{(n)}\circ A^{(n)}\; \quad\text{for all}\:n\geq 0.
\end{eqnarray*}
The dialgebra $(A,\cdot,\circ)$ is called \textbf{solvable} if there exists $m \ge 0$ such that $A^{(m)} = 0$.\par
The \textbf{lower central series} of $A$ is the sequence of $A$ given by
\begin{eqnarray*}
A^{1} := A, \qquad
A^{n} := \sum_{i=1}^{n-1} \bigl( A^{i}\!\cdot\! A^{n-i} + A^{i}\circ A^{n-i} \bigr) \quad\text{for all}\:n\geq 2.
\end{eqnarray*}
The dialgebra $(A,\cdot,\circ)$ is called \textbf{nilpotent} if there exists $m \ge 1$ such that $A^{m} = 0$.

\label{dialgebra nil4}
Let $(P, \cdot, \circ)$ be a finite-dimensional dialgebra. The following statements are equivalent:
\begin{enumerate}
\item \label{i}\(P\) is nilpotent;
\item \label{ii}If \(B \neq P\) is a subalgebra of \(P\), then there exists an element \(x \notin B\) such that \(x\cdot y,y\cdot x,x\circ y,y\circ x \in B\), for all \(y \in P\);
\item \label{iii} There is a basis \(\{x_1, \dots, x_n\}\) for \(P\) such that the matrices representing \(P_x, P'_x,Q_x\) and \(Q'_x\) with respect to this basis are strictly triangular, for all \(x \in P\);
\item \label{iv} There is a chain of ideals of \(P\) as follows:
 \begin{eqnarray*}
&&0 = P_{(0)} \subset P_{(1)} \subset \cdots \subset P_{(n)} = P,
 \end{eqnarray*}
 where \(\dim P_{(i)} = i\) and \(P\cdot  P_{(i)} +P_{(i)}\cdot P+ P_{(i)} \circ P+P\circ P_{(i)} \subseteq P_{(i-1)}\), for each $i=1,2,...,n$.
\end{enumerate}

By \cite{simple Novikov},  $B\circ C$ is an ideal of $P_N$. By Eq.~\eqref{transNP2}, we obtain
\begin{eqnarray*}
&&P\cdot (B\circ C)\subseteq (B\cdot P)\circ C+B\circ (C\cdot P)\subseteq B\circ C.
\end{eqnarray*}
This completes the proof.

~\cite[Proposition 2.20]{transposed N-P}
Let $(P,\cdot,\circ)$ be a {\transNovikovpoisson algebra}. Then the following identity holds for all $x,y,z\in P$:
\begin{eqnarray}
\label{Tid1}&&(x\circ y)\cdot z=(x\circ z)\cdot y.
\end{eqnarray}

\label{nil-soltrans}
Let $(P,\cdot, \circ )$ be a transposed Novikov-Poisson algebra. Then the following statements are equivalent:
\begin{enumerate}
\item[(i)] \( P \) is right nilpotent;
\item[(ii)] \( P^2 \) is nilpotent;
\item[(iii)] \( P \) is solvable.
\end{enumerate}

\label{ex1}
Let $P$ be a 3-dimensional vector space over $\mathbb{C}$ with a basis $\{e_1, e_2,e_3\}$.
By~\cite{transitive Novikov}, $(P, \circ)$ is a transitive (right nilpotent) Novikov algebra with the non-zero products given by
\begin{eqnarray*}
&&e_2 \circ e_2 = e_3\circ e_3=e_1.
\end{eqnarray*}
It is easy to see that it is solvable. By the method~\cite{transposed N-P}, there is a non-trivial transposed Novikov-Poisson algebra on it,
where the non-zero commutative associative products are given by
\begin{eqnarray*}
 && e_2 \cdot e_2 = e_2\cdot e_3=e_3\cdot e_2=e_3\cdot e_3=e_1.
\end{eqnarray*}
By a straightforward computation, we obtain $P^{(1)}=P^2=P_L^2=\mathbb{C}e_1$ and $(P^2)^1=P^{(2)}=P_L^3=0$. Hence, $P$ is solvable and right nilpotent, and $P^2$ is nilpotent.

By Proposition~\ref{idealpro1}, $B\circ N$ is an ideal of $P$. Since $B\circ N\subseteq B$, the minimality of $B$ implies that either $B\circ N=B$ or $B\circ N=0$. Because $N$ is Novikov nilpotent, we must have $B\circ N=0$. Similarly, we obtain $N\circ B=0$.\par
Moreover, by Eqs.~\eqref{transNP1} and~\eqref{transNP2}, we have
\begin{eqnarray*}
(B\cdot N)\cdot P = B\cdot(N\cdot P)  \subseteq B\cdot N
\end{eqnarray*}
and
\begin{eqnarray*}
(B\cdot N)\circ P+P\circ (B\cdot N) \subseteq(B\cdot P)\circ N+B\cdot (P\circ N)+(P\cdot B)\circ N\subseteq B\cdot N+B\circ N=B\cdot N.
\end{eqnarray*}
It follows that $B\cdot N$ is also an ideal of $P$ contained in $B$. Thus, by the minimality of $B$, we have either $B\cdot N=0$ or $B\cdot N=B$. Since $N$ is associative nilpotent, we conclude $B\cdot N=0$. Hence, we obtain $B\subseteq \operatorname{Ann}_P(N)$.

\label{nil-solNovikov}~\cite[Theorem 3.3]{Nilpotent Novikov}
Let $N$ be a Novikov algebra. Then the following statements are equivalent:
\begin{enumerate}
\item[(i)] \( N \) is right nilpotent;
\item[(ii)] \( N^2 \) is nilpotent;
\item[(iii)] \( N \) is solvable.
\end{enumerate}

Here we only prove the left nilpotent case.  The right nilpotent case is similar. By Proposition~\ref{idealpro2}, we obtain that $P\cdot B+P\circ B+C$ is an ideal of $P$. Thus we have $P\cdot B+P\circ B+C\subseteq C$ or $P\cdot B+P\circ B+C=B$. Suppose that the latter holds. Since $P$ is left nilpotent, we have
\begin{eqnarray*}
&&B=P\cdot B+P\circ B+C=P\cdot (P\cdot B+P\circ B)+P\circ (P\cdot B+P\circ B)+C+...=C,
\end{eqnarray*}
which leads to a contradiction. Hence, $P\cdot B+P\circ B\subseteq C$. Similarly, if $P$ is right nilpotent, then $B\cdot P+B\circ P\subseteq C$.

Let $B/C$ be a chief factor of $P$. Then we have $B\cdot P+B\circ P+P\circ B\subseteq C$. It implies that $\operatorname{dim}(B/C)=1$. So there is a chain of ideals of $P$
 \begin{eqnarray*}
&&0 = P_{(0)} \subset P_{(1)} \subset \cdots \subset P_{(n)} = P,
 \end{eqnarray*}
 where \(\dim P_{(i)} = i\) and \(P\cdot  P_{(i)} + P_{(i)} \circ P+P\circ P_{(i)} \subseteq P_{(i-1)}\). Hence, $P$ is nilpotent by Theorem~\ref{dialgebra nil4}.

Let \((P, \cdot, \circ)\) be a transposed Novikov-Poisson algebra. Then $P$ is called \textbf{metatrivial} (or \textbf{strongly metabelian}) if \(P\) is an extension of an abelian transposed Novikov-Poisson algebra by another abelian one, that is, if there exist two abelian transposed Novikov-Poison algebras \( V_1 \), \( V_2 \) and an exact sequence of algebra morphisms
\begin{eqnarray}\label{metaexact}
0 \longrightarrow V_1 \xrightarrow{i} P \xrightarrow{\pi} V_2 \longrightarrow 0 .
\end{eqnarray}

\label{metapro}
Let $(P,\cdot ,\circ)$ be a transposed Novikov-Poisson algebra. Then the following statements are equivalent:
\begin{enumerate}
    \item\label{meta1} \( P \) is metatrivial;
    \item \label{meta2}\( P \) is a solvable algebra with \( (c_1*_1c_2)*_2(c_3*_3c_4)= 0 \), where \( c_1,c_2,c_3,c_4 \in P \) and $*_1,*_2,*_3\in \{\cdot,\circ\}$;
    \item \label{meta3}The derived algebra \( P^2 \) is an abelian subalgebra of \( P \).
\end{enumerate}

Let $P$ be a 2-dimensional vector space over {\bf k} with a basis $\{a,b\}$. By~\cite{Nilpotent Novikov}, $(P, \circ)$ is a Novikov algebra with the non-zero products given by
\begin{eqnarray*}
&&a\circ b = b.
\end{eqnarray*}
Now we define the trivial associative products. It is easy to see that $P$ is a transposed Novikov-Poisson algebra and ${\bf k}a$ and ${\bf k}b$ are abelian subalgebras, and $(P,\cdot, \circ)$ is not nilpotent.
